CREATE TABLE mistri.command_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    CONSTRAINT command_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT command_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.command_receipt (
    id text NOT NULL COLLATE pg_catalog."C",
    app_id text NOT NULL COLLATE pg_catalog."C",
    store_id text NOT NULL COLLATE pg_catalog."C",
    source_id text NOT NULL COLLATE pg_catalog."C",
    realm text NOT NULL COLLATE pg_catalog."C",
    tenant_id text NOT NULL COLLATE pg_catalog."C",
    actor_id text NOT NULL COLLATE pg_catalog."C",
    command_id text NOT NULL COLLATE pg_catalog."C",
    command_version integer NOT NULL,
    idempotency_key text NOT NULL COLLATE pg_catalog."C",
    fingerprint text NOT NULL,
    result_json text NOT NULL,
    request_id text NOT NULL,
    completed_at timestamp with time zone NOT NULL,
    membership_id text NOT NULL COLLATE pg_catalog."C",
    membership_version text NOT NULL COLLATE pg_catalog."C",
    realm_version text NOT NULL COLLATE pg_catalog."C",
    roles_json text NOT NULL,
    deployment text NOT NULL COLLATE pg_catalog."C",
    target text NOT NULL,
    owners_json text NOT NULL,
    keys_json text NOT NULL,
    changes_json text NOT NULL,
    manifest_json text COLLATE pg_catalog."C",
    event_count integer,
    digest text COLLATE pg_catalog."C",
    xact_id xid8,
    CONSTRAINT command_receipt_changes_json_check CHECK (((octet_length(changes_json) <= 4194304) AND (json_typeof((changes_json)::json) = 'array'::text))),
    CONSTRAINT command_receipt_check CHECK (((realm = 'tenant'::text) OR (tenant_id = ''::text))),
    CONSTRAINT command_receipt_check1 CHECK ((((manifest_json IS NULL) = (event_count IS NULL)) AND ((manifest_json IS NULL) = (digest IS NULL)) AND ((manifest_json IS NULL) = (xact_id IS NULL)))),
    CONSTRAINT command_receipt_command_version_check CHECK ((command_version > 0)),
    CONSTRAINT command_receipt_digest_check CHECK ((digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT command_receipt_event_count_check CHECK (((event_count >= 1) AND (event_count <= 32))),
    CONSTRAINT command_receipt_keys_json_check CHECK (((octet_length(keys_json) <= 2097152) AND (json_typeof((keys_json)::json) = 'array'::text))),
    CONSTRAINT command_receipt_manifest_json_check CHECK ((((octet_length(manifest_json) >= 1) AND (octet_length(manifest_json) <= 65536)) AND (json_typeof((manifest_json)::json) = 'array'::text))),
    CONSTRAINT command_receipt_owners_json_check CHECK (((octet_length(owners_json) <= 65536) AND (json_typeof((owners_json)::json) = 'array'::text))),
    CONSTRAINT command_receipt_realm_check CHECK ((realm = ANY (ARRAY['tenant'::text, 'platform'::text]))),
    CONSTRAINT command_receipt_result_json_check CHECK (((octet_length(result_json) <= 16384) AND ((result_json)::json IS NOT NULL))),
    CONSTRAINT command_receipt_roles_json_check CHECK (((octet_length(roles_json) <= 65536) AND (json_typeof((roles_json)::json) = 'array'::text)))
);
CREATE TABLE mistri.event_event (
    event_id text NOT NULL COLLATE pg_catalog."C",
    receipt_id text NOT NULL COLLATE pg_catalog."C",
    ordinal integer NOT NULL,
    envelope_json text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT event_event_envelope_json_check CHECK ((((octet_length(envelope_json) >= 1) AND (octet_length(envelope_json) <= 131072)) AND (json_typeof((envelope_json)::json) = 'object'::text))),
    CONSTRAINT event_event_event_id_check CHECK ((octet_length(event_id) = 36)),
    CONSTRAINT event_event_ordinal_check CHECK (((ordinal >= 0) AND (ordinal <= 31))),
    CONSTRAINT event_event_receipt_id_check CHECK (((octet_length(receipt_id) >= 1) AND (octet_length(receipt_id) <= 128)))
);
CREATE TABLE mistri.event_meta (
    app_id text NOT NULL COLLATE pg_catalog."C",
    version integer NOT NULL,
    store_id text NOT NULL COLLATE pg_catalog."C",
    source_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT event_meta_app_id_check CHECK (((octet_length(app_id) >= 1) AND (octet_length(app_id) <= 128))),
    CONSTRAINT event_meta_source_id_check CHECK (((octet_length(source_id) >= 1) AND (octet_length(source_id) <= 128))),
    CONSTRAINT event_meta_store_id_check CHECK (((octet_length(store_id) >= 1) AND (octet_length(store_id) <= 256))),
    CONSTRAINT event_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.sequence_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    CONSTRAINT sequence_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT sequence_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.sequence_number (
    app_id text NOT NULL COLLATE pg_catalog."C",
    store_id text NOT NULL COLLATE pg_catalog."C",
    source_id text NOT NULL COLLATE pg_catalog."C",
    realm text NOT NULL COLLATE pg_catalog."C",
    tenant_id text NOT NULL COLLATE pg_catalog."C",
    name text NOT NULL COLLATE pg_catalog."C",
    per text NOT NULL COLLATE pg_catalog."C",
    value bigint NOT NULL,
    CONSTRAINT sequence_number_realm_check CHECK ((realm = ANY (ARRAY['tenant'::text, 'platform'::text]))),
    CONSTRAINT sequence_number_value_check CHECK ((value > 0))
);
